input double Tppoints = 200;  // Take Profit (10 pontos = 1 pip)
input double Slpoints = 200;  // Stop Loss (10 pontos = 1 pip)
input double OrderDistPoints = 100;  // Distância para abrir ordens (10 pontos = 1 pip)
input int BarsN = 5;  // Número de velas para cálculo de máxima/mínima

// Funções auxiliares
double findHigh(int bars);
double findLow(int bars);

//+------------------------------------------------------------------+
//| Função de inicialização do indicador                             |
//+------------------------------------------------------------------+
int OnInit()
{
    // Configuração dos buffers
    SetIndexBuffer(0, BuyEntryBuffer);
    SetIndexBuffer(1, SellEntryBuffer);
    SetIndexBuffer(2, TPBuffer);
    SetIndexBuffer(3, SLBuffer);

    // Configuração das setas
    PlotIndexSetInteger(0, PLOT_ARROW, 233);  // Código ASCII para seta para cima
    PlotIndexSetInteger(1, PLOT_ARROW, 234);  // Código ASCII para seta para baixo

    // Nome do indicador
    IndicatorSetString(INDICATOR_SHORTNAME, "Signal Indicator");

    return (INIT_SUCCEEDED);
}

//+------------------------------------------------------------------+
//| Função de cálculo do indicador                                   |
//+------------------------------------------------------------------+
int OnCalculate(const int rates_total,      // número total de barras
                const int prev_calculated,  // barras calculadas previamente
                const datetime &time[],     // tempos
                const double &open[],       // preços de abertura
                const double &high[],       // preços de máxima
                const double &low[],        // preços de mínima
                const double &close[],      // preços de fechamento
                const long &tick_volume[],
                const long &volume[],
                const int &spread[])
{
    int start = MathMax(prev_calculated - 1, BarsN);

    for (int i = start; i < rates_total; i++)
    {
        double highPoint = findHigh(BarsN);
        double lowPoint = findLow(BarsN);

        if (high[i] > highPoint)
        {
            BuyEntryBuffer[i] = high[i];
            TPBuffer[i] = high[i] + Tppoints * _Point;
            SLBuffer[i] = high[i] - Slpoints * _Point;
        }

        if (low[i] < lowPoint)
        {
            SellEntryBuffer[i] = low[i];
            TPBuffer[i] = low[i] - Tppoints * _Point;
            SLBuffer[i] = low[i] + Slpoints * _Point;
        }
    }

    return (rates_total);
}

//+------------------------------------------------------------------+
//| Função para encontrar a máxima                                   |
//+------------------------------------------------------------------+
double findHigh(int bars)
{
    double highest = 0;
    for (int i = 0; i < bars; i++)
    {
        double high = iHigh(_Symbol, PERIOD_CURRENT, i);
        if (high > highest) highest = high;
    }
    return highest;
}

//+------------------------------------------------------------------+
//| Função para encontrar a mínima                                   |
//+------------------------------------------------------------------+
double findLow(int bars)
{
    double lowest = DBL_MAX;
    for (int i = 0; i < bars; i++)
    {
        double low = iLow(_Symbol, PERIOD_CURRENT, i);
        if (low < lowest) lowest = low;
    }
    return lowest;
}
